// ===================================================
// INTELLIGENT TUTORING MATCHING ALGORITHM
// WITH SLOT RECOMMENDATION
// ===================================================

// Get inputs
const parentData = $('Extract Parent Input').item.json;
const teachersRaw = $input.all()[0]?.json || [];
const groupsRaw = $input.all()[1]?.json || [];

// Convert single items to arrays if needed
const teachers = Array.isArray(teachersRaw) ? teachersRaw : [teachersRaw].filter(Boolean);
const groups = Array.isArray(groupsRaw) ? groupsRaw : [groupsRaw].filter(Boolean);

console.log('Parent availability:', parentData.availability);
console.log('Teachers found:', teachers.length);
console.log('Groups found:', groups.length);

// ===================================================
// HELPER FUNCTIONS
// ===================================================

function parseTimeSlot(slot) {
  // Parse "Tue 5-6pm" into structured format
  const dayMap = {
    'mon': 'Monday', 'monday': 'Monday',
    'tue': 'Tuesday', 'tuesday': 'Tuesday',
    'wed': 'Wednesday', 'wednesday': 'Wednesday',
    'thu': 'Thursday', 'thursday': 'Thursday',
    'fri': 'Friday', 'friday': 'Friday',
    'sat': 'Saturday', 'saturday': 'Saturday',
    'sun': 'Sunday', 'sunday': 'Sunday'
  };

  const slotLower = slot.toLowerCase().trim();

  // Extract day
  let day = null;
  for (let [key, value] of Object.entries(dayMap)) {
    if (slotLower.startsWith(key)) {
      day = value;
      break;
    }
  }

  // Extract time
  const timeMatch = slotLower.match(/(\d{1,2})(?::(\d{2}))?\s*-\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/);

  if (!timeMatch) {
    return { day, raw: slot, startHour: null, endHour: null };
  }

  let startHour = parseInt(timeMatch[1]);
  let endHour = parseInt(timeMatch[3]);

  // Handle PM conversion
  if (slotLower.includes('pm') && startHour < 12) {
    startHour += 12;
  }
  if (slotLower.includes('pm') && endHour < 12) {
    endHour += 12;
  }

  return { day, raw: slot, startHour, endHour };
}

function parseAvailability(availStr) {
  // Convert "Tue 5-6pm, Thu 5-6pm" to array of parsed slots
  if (!availStr) return [];

  if (Array.isArray(availStr)) {
    return availStr.map(slot => parseTimeSlot(slot));
  }

  return availStr.split(',').map(slot => parseTimeSlot(slot.trim()));
}

function checkExactScheduleMatch(optionSlot, parentSlots) {
  // Check if option slot exactly matches any parent slot
  const optionParsed = parseTimeSlot(optionSlot);

  for (let parentSlot of parentSlots) {
    const parentParsed = parseTimeSlot(parentSlot);

    if (optionParsed.day === parentParsed.day &&
        optionParsed.startHour === parentParsed.startHour &&
        optionParsed.endHour === parentParsed.endHour) {
      return true;
    }
  }
  return false;
}

function checkPartialScheduleMatch(optionSlots, parentSlots) {
  // Check if any option slot matches parent availability
  for (let optionSlot of optionSlots) {
    const optionParsed = parseTimeSlot(optionSlot);

    for (let parentSlot of parentSlots) {
      const parentParsed = parseTimeSlot(parentSlot);

      // Same day is a partial match
      if (optionParsed.day === parentParsed.day) {
        return { matched: true, day: optionParsed.day };
      }
    }
  }
  return { matched: false };
}

function findAlternativeSlots(optionSlots, parentSlots) {
  // Suggest alternative slots that are close to parent's preference
  const alternatives = [];
  const parentParsed = parentSlots.map(s => parseTimeSlot(s));
  const optionParsed = optionSlots.map(s => parseTimeSlot(s));

  for (let optSlot of optionParsed) {
    for (let parSlot of parentParsed) {
      // Same day but different time
      if (optSlot.day === parSlot.day) {
        alternatives.push({
          slot: optSlot.raw,
          reason: `Same day (${optSlot.day}) as your preference`,
          priority: 1
        });
      }
      // Adjacent day
      else {
        alternatives.push({
          slot: optSlot.raw,
          reason: `Alternative day available`,
          priority: 2
        });
      }
    }
  }

  return alternatives.sort((a, b) => a.priority - b.priority);
}

function scoreOption(option, parent, type) {
  let score = 0;
  let reasons = [];
  let hasExactMatch = false;
  let suggestedSlots = [];

  // 1. SCHEDULE MATCH (50 points) - MOST CRITICAL
  if (type === 'group') {
    // For groups, check if the fixed schedule matches
    hasExactMatch = checkExactScheduleMatch(option.Schedule, parent.availability);

    if (hasExactMatch) {
      score += 50;
      reasons.push(`✓ Perfect schedule match: ${option.Schedule}`);
    } else {
      // Suggest this group with alternative time
      const alternatives = findAlternativeSlots([option.Schedule], parent.availability);
      if (alternatives.length > 0) {
        score += 20;
        suggestedSlots.push({
          original: option.Schedule,
          reason: alternatives[0].reason
        });
        reasons.push(`~ Alternative: ${option.Schedule} (${alternatives[0].reason})`);
      } else {
        score += 5;
        suggestedSlots.push({
          original: option.Schedule,
          reason: 'Different day/time available'
        });
        reasons.push(`~ Available: ${option.Schedule}`);
      }
    }
  } else {
    // For 1:1, check teacher's availability
    const teacherSlots = parseAvailability(option.Availability);
    const partialMatch = checkPartialScheduleMatch(teacherSlots.map(s => s.raw), parent.availability);

    if (partialMatch.matched) {
      score += 45;
      hasExactMatch = true;
      reasons.push(`✓ Teacher available on ${partialMatch.day}`);
    } else {
      // Suggest alternative slots from teacher's availability
      const alternatives = findAlternativeSlots(teacherSlots.map(s => s.raw), parent.availability);
      if (alternatives.length > 0) {
        score += 30;
        suggestedSlots = alternatives.slice(0, 2).map(alt => ({
          original: alt.slot,
          reason: alt.reason
        }));
        reasons.push(`~ Alternative slots available: ${alternatives.slice(0, 2).map(a => a.slot).join(', ')}`);
      } else {
        score += 15;
        suggestedSlots.push({
          original: teacherSlots[0]?.raw || 'Contact for availability',
          reason: 'Flexible scheduling possible'
        });
        reasons.push(`~ Flexible: ${teacherSlots[0]?.raw || 'Multiple times available'}`);
      }
    }
  }

  // 2. GROUP SIZE / PERSONALIZATION (25 points)
  if (type === 'group') {
    const capacity = option.Max_Size - option.Current_Size;
    const capacityScore = (capacity / option.Max_Size) * 25;
    score += capacityScore;

    if (option.Current_Size === 0) {
      reasons.push(`✓ New group - shape the learning environment`);
    } else if (capacity === 1) {
      reasons.push(`⚠ Last spot available`);
    } else {
      reasons.push(`✓ Small group (${option.Current_Size} student${option.Current_Size > 1 ? 's' : ''})`);
    }
  } else {
    score += 25;
    reasons.push(`✓ 100% personalized 1:1 attention`);
  }

  // 3. EXPERIENCE (15 points)
  const experience = option.Experience || '0 years';
  const years = parseInt(experience);

  if (years >= 5) {
    score += 15;
    reasons.push(`✓ Highly experienced (${experience})`);
  } else if (years >= 3) {
    score += 10;
    reasons.push(`✓ Experienced (${experience})`);
  } else {
    score += 5;
  }

  // 4. FOCUS AREA MATCH (10 points)
  if (type === 'group' && option.Focus_Area && parent.challenges) {
    const focusLower = option.Focus_Area.toLowerCase();
    const challengesLower = parent.challenges.toLowerCase();

    if (focusLower.includes(challengesLower) || challengesLower.includes(focusLower)) {
      score += 10;
      reasons.push(`✓ Specializes in ${option.Focus_Area.toLowerCase()}`);
    }
  }

  // 5. PREFERENCE BONUS (10 points)
  if (parent.preference && parent.preference.toLowerCase().includes('group') && type === 'group') {
    score += 10;
    reasons.push(`✓ Matches your group preference`);
  } else if (parent.preference && parent.preference.toLowerCase().includes('1:1') && type === '1:1') {
    score += 10;
    reasons.push(`✓ Matches your 1:1 preference`);
  }

  return { score, reasons, hasExactMatch, suggestedSlots };
}

// ===================================================
// PROCESS GROUPS
// ===================================================

const groupOptions = groups.map(group => {
  const { score, reasons, hasExactMatch, suggestedSlots } = scoreOption(group, parentData, 'group');

  return {
    id: group.Group_ID,
    type: 'Group',
    name: `${group.Subject} - ${group.Level}`,
    schedule: group.Schedule,
    teacher_id: group.Teacher_ID,
    current_size: parseInt(group.Current_Size) || 0,
    max_size: parseInt(group.Max_Size) || 3,
    focus_area: group.Focus_Area,
    score: score,
    reasons: reasons,
    hasExactMatch: hasExactMatch,
    suggestedSlots: suggestedSlots,
    raw_data: group
  };
});

// ===================================================
// PROCESS 1:1 OPTIONS
// ===================================================

const oneToOneOptions = teachers.map(teacher => {
  const { score, reasons, hasExactMatch, suggestedSlots } = scoreOption(teacher, parentData, '1:1');

  // Find best matching time slot
  const teacherSlots = parseAvailability(teacher.Availability);
  const parentSlots = parentData.availability;

  let bestSlot = teacherSlots[0]?.raw || 'Flexible';

  // Try to find exact match first
  for (let tSlot of teacherSlots) {
    if (checkExactScheduleMatch(tSlot.raw, parentSlots)) {
      bestSlot = tSlot.raw;
      break;
    }
  }

  return {
    id: teacher.Teacher_ID,
    type: '1:1',
    name: `1:1 with ${teacher.Name}`,
    schedule: bestSlot,
    teacher_name: teacher.Name,
    experience: teacher.Experience,
    hourly_rate: teacher.Hourly_Rate,
    score: score,
    reasons: reasons,
    hasExactMatch: hasExactMatch,
    suggestedSlots: suggestedSlots,
    raw_data: teacher
  };
});

// ===================================================
// COMBINE & RANK OPTIONS
// ===================================================

const allOptions = [...groupOptions, ...oneToOneOptions];

console.log('Total options before ranking:', allOptions.length);

// Sort by score (highest first)
allOptions.sort((a, b) => b.score - a.score);

// Prioritize exact matches at the top
const exactMatches = allOptions.filter(opt => opt.hasExactMatch);
const partialMatches = allOptions.filter(opt => !opt.hasExactMatch);

const rankedOptions = [...exactMatches, ...partialMatches];

// Get top 3
let top3 = rankedOptions.slice(0, 3);

// ===================================================
// ENSURE DIVERSITY
// ===================================================

if (top3.length > 0) {
  const hasGroup = top3.some(opt => opt.type === 'Group');
  const hasOneToOne = top3.some(opt => opt.type === '1:1');

  // If all top 3 are same type, force diversity
  if (!hasGroup && groupOptions.length > 0) {
    const topGroup = groupOptions.sort((a, b) => b.score - a.score)[0];
    top3[2] = topGroup;
  } else if (!hasOneToOne && oneToOneOptions.length > 0) {
    const topOneToOne = oneToOneOptions.sort((a, b) => b.score - a.score)[0];
    top3[2] = topOneToOne;
  }
}

// ===================================================
// HANDLE NO MATCHES SCENARIO
// ===================================================

if (top3.length === 0) {
  return {
    json: {
      submission_id: parentData.submission_id,
      parent_data: parentData,
      matched_options: [],
      no_matches: true,
      message: `We couldn't find exact matches for ${parentData.subject} at your preferred times. However, we have teachers available at alternative times. Would you like to see flexible scheduling options?`,
      all_available_teachers: teachers.map(t => ({
        name: t.Name,
        availability: t.Availability,
        experience: t.Experience
      })),
      all_available_groups: groups.map(g => ({
        name: `${g.Subject} - ${g.Level}`,
        schedule: g.Schedule,
        current_size: g.Current_Size,
        focus: g.Focus_Area
      }))
    }
  };
}

// ===================================================
// FORMAT OUTPUT
// ===================================================

return {
  json: {
    submission_id: parentData.submission_id,
    parent_data: parentData,
    matched_options: top3,
    no_matches: false,
    matching_summary: {
      total_groups_found: groupOptions.length,
      total_teachers_found: oneToOneOptions.length,
      exact_matches_found: exactMatches.length,
      top_score: top3[0]?.score || 0,
      matching_timestamp: new Date().toISOString()
    }
  }
};

const aiResponse = $input.first().json;
const matchData = $('Matching Algorithm').item.json;
const parentData = $('Extract Parent Input').item.json;

// Extract AI message
let aiMessage = '';
if (aiResponse.content && Array.isArray(aiResponse.content)) {
  aiMessage = aiResponse.content
    .filter(item => item.type === 'text')
    .map(item => item.text)
    .join('\n');
}

// Create booking buttons for each option
const bookingButtons = matchData.matched_options.map((opt, idx) => {
  const optionNum = idx + 1;
  let scheduleInfo = opt.schedule;

  // Add suggested slots if available
  if (!opt.hasExactMatch && opt.suggestedSlots && opt.suggestedSlots.length > 0) {
    scheduleInfo += ` (${opt.suggestedSlots[0].reason})`;
  }

  return {
    type: 'button',
    text: {
      type: 'plain_text',
      text: `Book Option ${optionNum}: ${opt.name}`,
      emoji: true
    },
    value: JSON.stringify({
      submission_id: matchData.submission_id,
      option_number: optionNum,
      option_id: opt.id,
      option_type: opt.type,
      schedule: opt.schedule,
      parent_email: parentData.parent_email,
      child_name: parentData.child_name
    }),
    action_id: `book_option_${optionNum}`
  };
});

return {
  json: {
    session_id: parentData.session_id,
    ai_message: aiMessage,
    booking_buttons: bookingButtons,
    matched_options: matchData.matched_options,
    submission_id: matchData.submission_id,
    parent_data: parentData
  }
};
